window.OVA_CONTENT={"slug":"seccion-05-bioeconomia-y-bioproductos","title":"Bioeconomía y bioproductos","minutes":45,"summary":"Evalúa biomasa, procesos y productos como bioplásticos, bioetanol, enzimas y biogás sin asumir sostenibilidad automática.","objective":"Comparar oportunidades de generación de valor mediante criterios técnicos, ambientales y económicos.","stages":[{"eyebrow":"Concepto","title":"1. Recursos biológicos con conocimiento","reading":"La bioeconomía articula recursos biológicos, conocimiento y tecnología para crear productos, procesos y servicios. No se limita a sustituir un insumo fósil por uno biológico.","application":"La sostenibilidad depende de cómo se obtiene la biomasa, qué se transforma y qué impactos produce el ciclo completo.","activity":{"type":"choice","question":"¿Qué definición es más completa?","options":["Uso responsable de recursos biológicos, conocimiento y tecnología","Venta de cualquier producto natural","Eliminación de toda actividad industrial"],"answer":[0],"success":"La bioeconomía integra recursos, innovación y gestión."}},{"eyebrow":"Bioproductos","title":"2. Rutas diferentes de transformación","reading":"Bioplásticos, bioetanol, enzimas y biogás parten de materias y procesos distintos. Cada ruta tiene requerimientos de calidad, escala, energía y mercado.","application":"La disponibilidad de biomasa no garantiza que todas las rutas sean viables.","activity":{"type":"match","question":"Relaciona producto y ruta general.","pairs":[{"label":"Biogás","value":"anaerobia","option":"Digestión anaerobia"},{"label":"Bioetanol","value":"fermentacion","option":"Fermentación de azúcares"},{"label":"Enzimas","value":"biocatalisis","option":"Producción de biocatalizadores"},{"label":"Bioplástico","value":"polimero","option":"Obtención de material polimérico"}],"answer":["anaerobia","fermentacion","biocatalisis","polimero"],"success":"Cada producto requiere una cadena tecnológica propia."}},{"eyebrow":"Modelo","title":"3. Del residuo al negocio","reading":"Una oportunidad necesita flujo estable de materia, tecnología apropiada, controles, producto definido, usuarios y una propuesta de valor. También requiere conocer regulación y destino de subproductos.","application":"La innovación fracasa si solo se prueba la conversión técnica y se ignoran logística y mercado.","activity":{"type":"order","question":"Ordena el análisis.","items":["Cuantificar biomasa","Caracterizar composición","Seleccionar proceso","Validar producto y controles","Evaluar mercado e impactos"],"answer":[0,1,2,3,4],"success":"La oportunidad conecta materia, proceso, producto y demanda."}},{"eyebrow":"Sostenibilidad","title":"4. Comparar el ciclo completo","reading":"Un bioproducto puede competir por suelo o agua, consumir energía, generar efluentes o desplazar usos existentes. También puede reducir residuos y emisiones si se diseña bien.","application":"La evaluación debe comparar una alternativa con una línea base equivalente.","activity":{"type":"multi","question":"Selecciona criterios relevantes.","options":["Origen de la biomasa","Consumo de energía y agua","Destino de residuos","Nombre atractivo del producto"],"answer":[0,1,2],"success":"El prefijo bio no reemplaza la evaluación."}},{"eyebrow":"Caso aplicado","title":"5. Residuos de yuca","reading":"Una planta genera cáscaras y efluentes ricos en materia orgánica. Considera biogás, alimento, compost o extracción de compuestos.","application":"La mejor ruta dependerá de composición, volúmenes, estacionalidad, riesgos, infraestructura y mercado regional.","activity":{"type":"choice","question":"¿Qué propuesta es más sólida?","options":["Comparar rutas con datos técnicos, ambientales y económicos","Escoger la tecnología más costosa","Elegir solo por ser novedosa"],"answer":[0],"success":"La decisión combina viabilidad y sostenibilidad."}}],"number":"05","references":["Cunningham, W. P. et al. (2023). Principios de Ciencias Ambientales. McGraw-Hill.","Smith, T. M. y Smith, R. L. (2007). Ecología. Pearson.","Hardin, J. y Lodolce, J. P. (2024). Becker. El mundo de la célula. Pearson.","Marino Buslje, C. y Parisi, G. (2019). Aprender para predecir: la bioinformática como herramienta de estudio en biología.","Hodson de Jaramillo, E. et al. (2019). La bioeconomía: nuevo marco para el crecimiento sostenible en América Latina."]};